            "modulePath": "server",
            "prefixItems": [
                {
                    "type": {
                        "$ref": "#/$defs/f32"
                    }
                }
            ],
            "reflectTypes": [
                "Component",
                "Default",
                "Deserialize",
                "Serialize"
            ],
            "shortPath": "Cube",
            "type": "array",
            "typePath": "server::Cube"
        }
