body_text:
## Issue

Bevy alpha blends UI/text in linear color space, whereas the web blends in sRGB color space.

## Comparison (AI generated)

Bevy on left, web on right.
<img width="1316" height="540" alt="Image" src="https://github.com/user-attachments/assets/3a706d45-b5ac-4f0f-9471-bf6f5f811181" />

## Bevy

```rust
use bevy::{
    prelude::*,
    text::{DefaultFontSource, LineHeight},
    window::WindowResolution,
};

const SAMPLE: &str = "Hamburgefonstiv 0123";

fn main() {
    App::new()
        .insert_resource(ClearColor(Color::WHITE))
        .add_plugins(DefaultPlugins.set(WindowPlugin {
            primary_window: Some(Window {
                resolution: WindowResolution::new(640, 360).with_scale_factor_override(1.0),
                ..default()
            }),
            ..default()
        }))
        .add_systems(Startup, setup)
        .run();
}

fn setup(mut commands: Commands, assets: Res<AssetServer>, mut font: ResMut<DefaultFontSource>) {
    font.0 = assets.load::<Font>("fonts/MonaSans-VariableFont.ttf").into();
    commands.spawn(Camera2d);

    commands
        .spawn((
            Node {
                width: px(640),
                height: px(360),
                flex_direction: FlexDirection::Column,
                padding: UiRect::all(px(16)),
                row_gap: px(16),
                ..default()
            },
            BackgroundColor(Color::WHITE),
        ))
        .with_children(|root| {
            // Black at decreasing alpha over white.
            root.spawn(Node {
                column_gap: px(16),
                ..default()
            })
            .with_children(|row| {
                for alpha in [0.8, 0.5, 0.2] {
                    row.spawn((
                        Node {
                            width: px(120),
                            height: px(60),
                            ..default()
                        },
                        BackgroundColor(Color::srgba(0.0, 0.0, 0.0, alpha)),
                    ));
                }
            });

            // Dark text on light, then light text on dark.
            for (background, foreground) in [(Color::WHITE, Color::BLACK), (Color::BLACK, Color::WHITE)] {
                root.spawn((
                    Node {
                        flex_direction: FlexDirection::Column,
                        padding: UiRect::all(px(8)),
                        ..default()
                    },
                    BackgroundColor(background),
