```rust
use anyhow::Result;
use wasmtime::{Config, Engine, Linker, Module, Store};
use wasmtime_wasi::WasiCtxBuilder;
use wasmtime_wasi_nn::{witx::WasiNnCtx, InMemoryRegistry, Registry};

const MARKER: &[u8; 16] = b"HOSTSECRET_C0DE!";

struct Ctx {
    wasi: wasmtime_wasi::p1::WasiP1Ctx,
    nn: WasiNnCtx,
}

fn main() -> Result<()> {
    let wasm = std::env::args().nth(1).expect("usage: host <guest.wasm>");
    let engine = Engine::new(&Config::new())?;
    let module = Module::from_file(&engine, &wasm)?;
    let nn = WasiNnCtx::new(
        wasmtime_wasi_nn::backend::list(),
        Registry::from(InMemoryRegistry::new()),
    );
    let wasi = WasiCtxBuilder::new().inherit_stdio().build_p1();
    let mut store = Store::new(&engine, Ctx { wasi, nn });
    let mut linker = Linker::new(&engine);
    wasmtime_wasi::p1::add_to_linker_sync(&mut linker, |c: &mut Ctx| &mut c.wasi)?;
    wasmtime_wasi_nn::witx::add_to_linker(&mut linker, |c: &mut Ctx| &mut c.nn)?;
    linker.func_wrap("env", "seed", || seed())?;
    let instance = linker.instantiate(&mut store, &module)?;
    instance.get_typed_func::<(), ()>(&mut store, "_start")?.call(&mut store, ())?;
    Ok(())
}

/// Fill freed host heap chunks with a marker pattern. Small sprays on purpose:
/// glibc recycles chunk contents deterministically; macOS keeps recently freed
/// blocks in per-CPU magazine caches (bulk frees are MADV_FREE'd and may be
/// reclaimed as zero pages).
fn seed() {
    for _ in 0..4 {
        let mut hold: Vec<Vec<u8>> = Vec::new();
        for _ in 0..16 {
            let mut v: Vec<u8> = Vec::with_capacity(4096);
            unsafe { v.set_len(4096) };
            for chunk in v.chunks_mut(MARKER.len()) { chunk.copy_from_slice(MARKER) }
            hold.push(v);
        }
        drop(hold);
    }
    eprintln!("[host] seeded freed heap chunks with marker");
}
```

