fn engine() -> Result<Engine> {
    let mut pool = PoolingAllocationConfig::default();
    pool.memory_protection_keys(Enabled::Yes);
    pool.total_memories(32);
    pool.linear_memory_keep_resident(65536);
    let mut config = Config::new();
    config.allocation_strategy(InstanceAllocationStrategy::Pooling(pool));
    Engine::new(&config)
}

fn main() -> Result<()> {
    let (tx, rx) = mpsc::channel::<Store<()>>();
    let pre = std::thread::spawn(move || {
        let store = rx.recv().unwrap();
        eprintln!("dropping store on other thread...");
        drop(store);
        eprintln!("dropped");
