	"net/http"
	"sync"
	"sync/atomic"
	"syscall"
	"testing"
	"time"

	"github.com/caddyserver/caddy/v2"
)

// reloadTestConfig serves body on addr, with nothing else running.
func reloadTestConfig(addr, body string) []byte {
	return fmt.Appendf(nil, `{
		"admin": {"disabled": true},
		"logging": {"logs": {"default": {"level": "ERROR"}}},
		"apps": {"http": {"servers": {"reload": {
			"listen": [%q],
			"routes": [{"handle": [{"handler": "static_response", "body": %q}]}]
		}}}}
	}`, addr, body)
}

func freeAddr(t *testing.T) string {
	t.Helper()
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	addr := ln.Addr().String()
	ln.Close()
	return addr
}

func loadOrFatal(t *testing.T, cfg []byte) {
	t.Helper()
	if err := caddy.Load(cfg, true); err != nil {
		t.Fatalf("loading config: %v", err)
	}
}

// ask sends a GET on conn and reads the answer.
func ask(conn net.Conn) (*http.Response, error) {
	if _, err := io.WriteString(conn, "GET / HTTP/1.1\r\nHost: reload.test\r\nConnection: close\r\n\r\n"); err != nil {
		return nil, err
	}
	resp, err := http.ReadResponse(bufio.NewReader(conn), nil)
	if err != nil {
		return nil, err
	}
	_, err = io.ReadAll(resp.Body)
	resp.Body.Close()
	return resp, err
}

// A connection the old config accepted, whose request arrives only once
// the old server is being stopped, is answered: by the old config, which
// reads it before it shuts down. (Shutdown begun first would close it
// unanswered: net/http's conn.serve closes a request read after it.)
func TestReloadAnswersConnectionAcceptedBeforeIt(t *testing.T) {
	addr := freeAddr(t)
	loadOrFatal(t, reloadTestConfig(addr, "one"))
	t.Cleanup(func() { _ = caddy.Stop() })

	conn, err := net.Dial("tcp", addr)
	if err != nil {
		t.Fatal(err)
	}
	defer conn.Close()
	// accepted by the first config's server (its accept loop is idle)
	time.Sleep(100 * time.Millisecond)

	loadOrFatal(t, reloadTestConfig(addr, "two"))
	// the first config's server is being stopped by now
	time.Sleep(100 * time.Millisecond)

	conn.SetDeadline(time.Now().Add(10 * time.Second))
	resp, err := ask(conn)
	if err != nil {
		t.Fatalf("a connection accepted before the reload, its request sent after: closed unanswered (%v)", err)
	}
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("status %d", resp.StatusCode)
	}

	// and the second config serves new connections
	c2, err := net.Dial("tcp", addr)
	if err != nil {
		t.Fatal(err)
	}
	defer c2.Close()
	c2.SetDeadline(time.Now().Add(10 * time.Second))
	if resp, err := ask(c2); err != nil || resp.StatusCode != http.StatusOK {
		t.Fatalf("after the reload: %v %v", resp, err)
	}
}

// Back-to-back reloads under load: a client on a new connection that takes
// its time to send its request (up to 20ms, as a loaded client or a far one
// does) is never closed unanswered. A reset is counted apart and not failed:
// a connection the kernel queued on the old SO_REUSEPORT listener when it
// closes is reset (on Linux, unless net.ipv4.tcp_migrate_req hands it to
// the new one), which is the kernel's doing, not the server's.
func TestReloadLoopClosesNoConnectionUnanswered(t *testing.T) {
	if testing.Short() {
		t.Skip("reload loop")
	}
	addr := freeAddr(t)
	loadOrFatal(t, reloadTestConfig(addr, "0"))
	t.Cleanup(func() { _ = caddy.Stop() })

	var (
		stop                 atomic.Bool
		answered, unanswered atomic.Int64
		reset, other         atomic.Int64
		wg                   sync.WaitGroup
		mu                   sync.Mutex
		samples              []string
	)
	note := func(s string) {
		mu.Lock()
		if len(samples) < 5 {
			samples = append(samples, s)
		}
		mu.Unlock()
	}
	for range 16 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for !stop.Load() {
				conn, err := net.DialTimeout("tcp", addr, 5*time.Second)
				if errors.Is(err, syscall.ECONNRESET) {
					reset.Add(1) // queued on the closed listener (macOS, BSD)
					continue
				}
				if err != nil {
					other.Add(1)
					note("dial: " + err.Error())
					continue
				}
				time.Sleep(time.Duration(rand.IntN(20_000)) * time.Microsecond)
				conn.SetDeadline(time.Now().Add(15 * time.Second))
				resp, err := ask(conn)
				conn.Close()
				switch {
				case err == nil && resp.StatusCode == http.StatusOK:
					answered.Add(1)
				case errors.Is(err, io.EOF) || errors.Is(err, io.ErrUnexpectedEOF):
					unanswered.Add(1)
					note(err.Error())
				case errors.Is(err, syscall.ECONNRESET) || errors.Is(err, syscall.EPIPE):
					reset.Add(1)
				default:
					other.Add(1)
					note(fmt.Sprintf("%v %v", resp, err))
				}
			}
		}()
	}

	time.Sleep(200 * time.Millisecond)
	const reloads = 60
	for i := 1; i <= reloads; i++ {
		loadOrFatal(t, reloadTestConfig(addr, fmt.Sprint(i)))
		time.Sleep(time.Duration(rand.IntN(10)) * time.Millisecond)
	}
	time.Sleep(200 * time.Millisecond)
	stop.Store(true)
	wg.Wait()

	t.Logf("%d reloads: %d answered, %d closed unanswered, %d reset, %d other",
		reloads, answered.Load(), unanswered.Load(), reset.Load(), other.Load())
	if answered.Load() < reloads {
		t.Fatalf("too few requests: %d", answered.Load())
	}
	if n := unanswered.Load(); n > 0 {
		t.Fatalf("%d connections closed unanswered across %d reloads, e.g. %v", n, reloads, samples)
	}
	if n := other.Load(); n > 0 {
		t.Fatalf("%d requests failed otherwise, e.g. %v", n, samples)
	}
}
